import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)
MARK = "\x00"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def parse_changelog(text):
    releases = []
    current = None
    for line in text.splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def clean_body(lines):
    """Strip HTML comments and collapse blank lines."""
    raw = "\n".join(lines)
    # Replace each comment with a marker so we know which lines were touched.
    marked = COMMENT.sub(MARK, raw)
    out = []
    for line in marked.split("\n"):
        if MARK in line:
            line = line.replace(MARK, "").rstrip()
        if not line.strip():
            if not out or out[-1] == "":
                continue
            line = ""
        out.append(line)
    return "\n".join(out).strip("\n")


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = clean_body(release.body)
            if release.date:
                title = f"# {release.version} ({release.date})"
            else:
                title = f"# {release.version}"
            return f"{title}\n\n{body}\n"
    raise LookupError(version)

